CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL, name VARCHAR(255), age INT, balance DECIMAL(10,2));
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, total DECIMAL(12,2), status VARCHAR(20));
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT, amount DECIMAL(12,2), FOREIGN KEY (order_id) REFERENCES orders(id));
CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, message TEXT);

-- Portable row generator: 4 digits x 10 = 10000 combos, filtered per table.
-- (Recursive CTEs hit dialect-specific depth limits.)
INSERT INTO users (email, name, age, balance)
SELECT CONCAT('user', g, '@example.com'), CONCAT('User ', g),
       CASE WHEN g % 7 = 0 THEN NULL WHEN g % 11 = 0 THEN -5 ELSE g % 120 END,
       (g % 1000) * 1.5
FROM (
  SELECT d1.n + d2.n * 10 + d3.n * 100 + d4.n * 1000 AS g
  FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d1,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d2,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d3,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d4
  WHERE d1.n + d2.n * 10 + d3.n * 100 + d4.n * 1000 < 2000
) seq;

INSERT INTO users (email, name, age) VALUES
  ('dup@example.com', 'Dup A', 30),
  ('dup@example.com', 'Dup B', 40),
  (CONCAT(REPEAT('x', 50), '@example.com'), 'Long', 50);

INSERT INTO orders (user_id, total, status)
SELECT CASE WHEN g % 97 = 0 THEN 999999 ELSE (g % 2000) + 1 END,
       g * 1.5, ELT(1 + g % 4, 'new', 'paid', 'shipped', 'cancelled')
FROM (
  SELECT d1.n + d2.n * 10 + d3.n * 100 + d4.n * 1000 AS g
  FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d1,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d2,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d3,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d4
  WHERE d1.n + d2.n * 10 + d3.n * 100 + d4.n * 1000 BETWEEN 1 AND 5000
) seq;

INSERT INTO payments (order_id, amount)
SELECT id, total FROM orders;

INSERT INTO logs (message)
SELECT CONCAT('log ', g)
FROM (
  SELECT d1.n + d2.n * 10 + d3.n * 100 + d4.n * 1000 AS g
  FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d1,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d2,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d3,
       (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d4
  WHERE d1.n + d2.n * 10 + d3.n * 100 + d4.n * 1000 BETWEEN 1 AND 5000
) seq;
